<?php
namespace Joomla\Component\Academy\Site\View\Category;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;use Joomla\CMS\Pagination\Pagination;use Joomla\Registry\Registry;use Joomla\Component\Academy\Administrator\Helper\CategoriesHelper;
final class HtmlView extends BaseHtmlView { public $category;public array $items=[];public $pagination;public $params;public array $lead_items=[],$intro_items=[],$link_items=[];public function display($tpl=null):void{$app=Factory::getApplication();$db=CategoriesHelper::db();$id=$app->getInput()->getInt('id');$this->category=$db->setQuery($db->createQuery()->select('*')->from('#__academy_categories')->where('id='.(int)$id)->where('published=1')->whereIn('access',$app->getIdentity()->getAuthorisedViewLevels()))->loadObject();if(!$this->category)throw new \RuntimeException('Category not found',404);$q=$db->createQuery()->select('p.*')->from('#__academy AS p')->where('p.catid='.(int)$id)->where('p.state=1')->whereIn('p.access',$app->getIdentity()->getAuthorisedViewLevels())->where('(p.publish_up IS NULL OR p.publish_up<=UTC_TIMESTAMP())')->where('(p.publish_down IS NULL OR p.publish_down>=UTC_TIMESTAMP())')->order('CASE WHEN p.publish_up IS NULL THEN p.created ELSE p.publish_up END DESC');$all=$db->setQuery($q)->loadObjectList()?:[];foreach($all as $item){$item->params=new Registry($item->options??'{}');$item->slug=$item->id.':'.$item->alias;}$limit=max(1,(int)$app->get('list_limit',20));$start=$app->getInput()->getUint('limitstart',0);$this->items=array_slice($all,$start,$limit);$this->pagination=new Pagination(count($all),$start,$limit);$this->params=$app->getParams();$this->getDocument()->setTitle($this->category->title);parent::display($tpl);}}
